Q: String hashing ignoring order A: <p>Sorting the characters of each string alphabetically before calculating the hash probably won't give you the fastest results. I would recommend just counting the occurrences of each character and using that information to calculate the hash instead.</p>
<p>If you're not bothered about capitalization, then a function like this should work fairly well. This returns 32-bit hash values:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const encoder = new TextEncoder();
const hash = (str) =&gt; {
    const bytes = encoder.encode(str);
    const buckets = new Uint8Array(32);
    // count occurrences of each character
    bytes.forEach((b) =&gt; {
        buckets[b &amp; 0x1f]++;
    });
    // generate hash value using integer arithmetic
    let hash = 0n;
    buckets.forEach((n) =&gt; {
        // Calculate 32-bit hash. For smaller hashes, use
        // a smaller prime and bit mask (e.g., 367n and
        // 0xffffn for 16-bit hashes)
        hash = (hash * 92693n + BigInt(n)) &amp; 0xffffffffn;
    });
    return Number(hash);
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;!DOCTYPE html&gt;
&lt;html lang="en"&gt;
&lt;head&gt;
  &lt;title&gt;String hash ignoring order&lt;/title&gt;
&lt;/head&gt;
&lt;body&gt;
&lt;label&gt;Enter text: &lt;input type="text"
    onkeyup="document.querySelector('#hashout').innerHTML = hash(this.value);"/&gt;&lt;/label&gt;&lt;br&gt;
&lt;label&gt;Hash value: &lt;span id="hashout"&gt;&lt;/span&gt;
&lt;/body&gt;
&lt;/html&gt;</code></pre>
</div>
</div>
</p>
